function c(t){return String(t||"").toLowerCase().trim().replace(/[^a-z0-9]+/g,"-").replace(/(^-|-$)/g,"")}function i(t){return/^[a-z0-9]+(-[a-z0-9]+)*$/.test(t)}function a(t){return/^[a-z0-9][a-z0-9-]*$/.test(t)}function s(t){if(!t)return!0;try{let e=new URL(t);return e.protocol==="http:"||e.protocol==="https:"}catch{return!1}}function l(t){let e=t.lastIndexOf(".");return e<=0?`${t} (copy)`:`${t.slice(0,e)} (copy)${t.slice(e)}`}function f(t,e){let n=new Set((e||[]).map(p=>String(p||"").toLowerCase())),r=`${t} (Copy)`,o=2;for(;n.has(r.toLowerCase());)r=`${t} (Copy ${o})`,o+=1;return r}export{c as a,i as b,a as c,s as d,l as e,f};
